#include <stdlib.h>
#include <string.h>

/* Used by the tests: leave this as it is. */
static int cmp_int(const void *a, const void *b) { int x = *(const int *)a, y = *(const int *)b; return (x > y) - (x < y); }

typedef struct { unsigned char *data; size_t len, cap, elem; } Vec;

Vec vec_new(size_t elem) { Vec v = {NULL, 0, 0, elem}; return v; }

int vec_push(Vec *v, const void *item)
{
    if (v->len == v->cap) {
        size_t cap = v->cap ? v->cap * 2 : 4;
        unsigned char *p = realloc(v->data, cap * v->elem);
        if (!p) return -1;
        v->data = p;
        v->cap = cap;
    }
    memcpy(v->data + v->len * v->elem, item, v->elem);
    v->len++;
    return 0;
}

void *vec_at(const Vec *v, size_t i)
{
    return i < v->len ? v->data + i * v->elem : NULL;
}

int vec_remove(Vec *v, size_t i, void *out)
{
    if (i >= v->len) return -1;
    unsigned char *at = v->data + i * v->elem;
    if (out) memcpy(out, at, v->elem);
    memmove(at, at + v->elem, (v->len - i - 1) * v->elem);
    v->len--;
    return 0;
}

void vec_sort(Vec *v, int (*cmp)(const void *, const void *))
{
    if (v->len > 1) qsort(v->data, v->len, v->elem, cmp);
}

void vec_free(Vec *v)
{
    free(v->data);
    v->data = NULL;
    v->len = v->cap = 0;
}

unitTests:
TEST("push and read ints") { Vec v = vec_new(sizeof(int)); for (int i = 0; i < 100; i++) CHECK_EQ(vec_push(&v, &i), 0); CHECK_EQ((int)v.len, 100); CHECK_EQ(*(int *)vec_at(&v, 42), 42); CHECK(vec_at(&v, 100) == NULL); vec_free(&v); CHECK(v.data == NULL); }
TEST("structs are copied") { struct rec { char name[8]; int score; }; Vec v = vec_new(sizeof(struct rec)); struct rec a = {"ada", 91}; vec_push(&v, &a); a.score = 0; struct rec *r = vec_at(&v, 0); CHECK_STR(r->name, "ada"); CHECK_EQ(r->score, 91); vec_free(&v); }
TEST("remove keeps the order") { Vec v = vec_new(sizeof(int)); for (int i = 1; i <= 5; i++) vec_push(&v, &i); int got = 0; CHECK_EQ(vec_remove(&v, 1, &got), 0); CHECK_EQ(got, 2); CHECK_EQ((int)v.len, 4); CHECK_EQ(*(int *)vec_at(&v, 1), 3); CHECK_EQ(*(int *)vec_at(&v, 3), 5); CHECK_EQ(vec_remove(&v, 3, NULL), 0); CHECK_EQ(vec_remove(&v, 9, NULL), -1); CHECK_EQ((int)v.len, 3); vec_free(&v); }
TEST("sort") { Vec v = vec_new(sizeof(int)); int xs[] = {5, -1, 9, 3}; for (int i = 0; i < 4; i++) vec_push(&v, &xs[i]); vec_sort(&v, cmp_int); CHECK_EQ(*(int *)vec_at(&v, 0), -1); CHECK_EQ(*(int *)vec_at(&v, 3), 9); vec_free(&v); }

